"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


_NUM = r"(?:0|[1-9][0-9]*)"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
_BUILD_ID = r"[0-9A-Za-z-]+"
_FULL_RE = re.compile(
    rf"({_NUM})\.({_NUM})\.({_NUM})"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+({_BUILD_ID}(?:\.{_BUILD_ID})*))?"
)
_NUM_RE = re.compile(_NUM)
_WILD = ("x", "X", "*")


def _parse_full(s):
    """Return (major, minor, patch, prerelease_tuple) or raise RangeError."""
    if not isinstance(s, str):
        raise RangeError(f"malformed version: {s!r}")
    m = _FULL_RE.fullmatch(s)
    if m is None:
        raise RangeError(f"malformed version: {s!r}")
    pre = tuple(m.group(4).split(".")) if m.group(4) else ()
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), pre)


def _cmp_pre(a, b):
    # Both non-empty or handled by caller.
    for x, y in zip(a, b):
        if x == y:
            continue
        xd, yd = x.isdigit(), y.isdigit()
        if xd and yd:
            return -1 if int(x) < int(y) else 1
        if xd:
            return -1
        if yd:
            return 1
        return -1 if x < y else 1
    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1


def _cmp(a, b):
    ta, tb = a[:3], b[:3]
    if ta != tb:
        return -1 if ta < tb else 1
    pa, pb = a[3], b[3]
    if not pa and not pb:
        return 0
    if not pa:
        return 1
    if not pb:
        return -1
    return _cmp_pre(pa, pb)


def _parse_partial(s):
    """Parse a possibly partial version.

    Returns (nums, pre) where nums is the list of specified numeric
    components (0-3 long) and pre is the prerelease tuple (only for full).
    """
    if not s:
        raise RangeError("empty version")
    if "-" in s or "+" in s:
        v = _parse_full(s)
        return [v[0], v[1], v[2]], v[3]
    parts = s.split(".")
    if len(parts) > 3:
        raise RangeError(f"malformed version: {s!r}")
    nums = []
    wild = False
    for p in parts:
        if p in _WILD:
            wild = True
        elif wild or _NUM_RE.fullmatch(p) is None:
            raise RangeError(f"malformed version: {s!r}")
        else:
            nums.append(int(p))
    return nums, ()


def _complete(nums, pre):
    return (*nums, *([0] * (3 - len(nums))), pre)


def _bump(nums, idx):
    """Version tuple with component idx incremented, the rest zeroed."""
    v = list(nums) + [0] * (3 - len(nums))
    v = v[:idx] + [v[idx] + 1] + [0] * (2 - idx)
    return (v[0], v[1], v[2], ())


def _parse_comparator(tok):
    op = ""
    for cand in (">=", "<=", ">", "<", "=", "^", "~"):
        if tok.startswith(cand):
            op = cand
            break
    body = tok[len(op):]
    nums, pre = _parse_partial(body)
    n = len(nums)
    if op in (">", ">=", "<", "<="):
        if n != 3:
            raise RangeError(f"operator needs a full version: {tok!r}")
        return [(op, (*nums, pre))]
    if op in ("^", "~"):
        if n == 0:
            raise RangeError(f"missing major: {tok!r}")
        lower = (">=", _complete(nums, pre))
        if op == "~":
            idx = 1 if n >= 2 else 0
        else:
            idx = None
            for i in range(n):
                if nums[i] != 0:
                    idx = i
                    break
            if idx is None:
                idx = n - 1
        return [lower, ("<", _bump(nums, idx))]
    # bare or '='
    if n == 0:
        return [(">=", (0, 0, 0, ()))]
    if n == 3:
        return [("=", (*nums, pre))]
    return [(">=", _complete(nums, ())), ("<", _bump(nums, n - 1))]


def _parse_hyphen(a, b):
    an, apre = _parse_partial(a)
    bn, bpre = _parse_partial(b)
    if not an or not bn:
        raise RangeError("hyphen range bounds need a major component")
    lower = (">=", _complete(an, apre))
    if len(bn) == 3:
        upper = ("<=", (*bn, bpre))
    else:
        upper = ("<", _bump(bn, len(bn) - 1))
    return [lower, upper]


def _parse_set(text):
    tokens = text.split()
    if not tokens:
        raise RangeError("empty comparator set")
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError(f"malformed hyphen range: {text!r}")
        return _parse_hyphen(tokens[0], tokens[2])
    prims = []
    for tok in tokens:
        prims.extend(_parse_comparator(tok))
    return prims


def _parse_range(expr):
    if not isinstance(expr, str):
        raise RangeError("range must be a string")
    if expr.strip() == "":
        return [[(">=", (0, 0, 0, ()))]]
    return [_parse_set(part) for part in expr.split("||")]


def _holds(op, v, p):
    c = _cmp(v, p)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    return c <= 0


def _satisfies(v, comp_set):
    for op, p in comp_set:
        if not _holds(op, v, p):
            return False
    if v[3]:
        return any(p[3] and p[:3] == v[:3] for _, p in comp_set)
    return True


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    sets = _parse_range(range_expr)
    parsed = [_parse_full(s) for s in versions]
    best = None
    best_v = None
    for s, v in zip(versions, parsed):
        if best_v is not None and _cmp(v, best_v) <= 0:
            continue
        if any(_satisfies(v, cs) for cs in sets):
            best, best_v = s, v
    return best
